namespace {

constexpr double kDuration = 240;
constexpr double kBpm = 138;
constexpr double kOrigin = 0.08;
using Events = std::array<std::vector<mixxx::BeatClockEvent>, 4>;

Events makeEvents(
        const std::function<double(double)>& displacement =
                [](double) { return 0; },
        bool hats = true,
        double bpm = kBpm) {
    Events events;
    for (int eighth = 0;; ++eighth) {
        const double base = kOrigin + eighth * 30 / bpm;
        const double time = base + displacement(base);
        if (time >= kDuration) {
            break;
        }
        for (size_t band = 0; band < events.size(); ++band) {
            if (eighth % 2 == 0) {
                events[band].push_back({time, 1});
            } else if (hats) {
                events[band].push_back({time + 0.004, band < 2 ? 0.08 : 0.35});
            }
        }
    }
    return events;
}

double nearestBeatError(const std::vector<double>& beats, double time) {
    const auto right = std::lower_bound(beats.begin(), beats.end(), time);
    double error = right == beats.end() ? 1 : std::abs(*right - time);
    if (right != beats.begin()) {
        error = std::min(error, std::abs(*(right - 1) - time));
    }
    return error;
}

} // namespace

TEST(BeatClockRecoveryTest, CorrectsHalfTempoFromSustainedMultiBandPulses) {
    const auto clock = mixxx::recoverBeatClock(makeEvents(), kBpm / 2, kDuration);
    ASSERT_TRUE(clock);
    EXPECT_NEAR(clock->harmonicRatio, 2, 1e-8);
    EXPECT_NEAR(clock->bpm, kBpm, 0.03);
    EXPECT_TRUE(clock->constant);
}

