    const auto warp = [](double time) {
        return 0.11 * std::sin(2 * std::acos(-1.0) * time / kDuration);
    };
    auto events = makeEvents(warp);
    for (double base = 100; base < 180; base += 45 / kBpm) {
        for (const size_t band : {size_t(2), size_t(3)}) {
            events[band].push_back({base + warp(base), 0.35});
        }
    }
    const auto clock = mixxx::recoverBeatClock(events, kBpm, kDuration);
    ASSERT_TRUE(clock);
    EXPECT_NEAR(clock->harmonicRatio, 1, 1e-8);
    EXPECT_FALSE(clock->constant);
    EXPECT_GT(clock->driftSeconds, 0.06);
